// plugins/hook_eval.js
const express = require('express');
const app = express();
app.use(express.json());

app.post('/plugins/hook', (req, res) => {
  const hook = req.body.hook;
  // 插件钩子直接求值执行
  const fn = eval('(' + hook + ')');
  fn();
  res.json({ ok: true });
});
app.listen(8080);
```

